import React, { ReactNode } from 'react';
import ScrollReveal from '@/components/ui/fadeInOnScroll';
import ClientOnly from '@/components/ClientOnly';
import * as styles from './sectionWrapper.module.css';

interface SectionWrapperProps {
    title: string;
    section_id: string;
    children: ReactNode;
}

const SectionWrapper: React.FC<SectionWrapperProps> = ({ title, section_id, children }) => {
    return (
        <ClientOnly fallback={
            <section className={styles.wrapper_section} id={section_id}>
                <h2 className={styles.section_title}>{title}</h2>
                <div className={styles.section_content}>
                    {children}
                </div>
            </section>
        }>
            <ScrollReveal>
                <section className={styles.section_content} id={section_id}>
                    <h2 className={styles.section_title}>{title}</h2>
                    {children}
                </section>
            </ScrollReveal>
        </ClientOnly>
    );
};

export default SectionWrapper;
