import React, { Suspense, lazy, useState, useEffect, useCallback } from "react";

import type { PageProps } from "gatsby";
import Layout from "@/components/Layout";
import Home from "../components/Home";
import Seo from "@/components/Seo";
import SectionWrapper from "@/components/sections/sectionWrapper";
import Loader from "@/components/ui/loader"; // ✅ імпорт

// Lazy sections
const About = lazy(() => import("@/components/sections/about"));
const Skills = lazy(() => import("@/components/sections/skills"));
const ProjectsList = lazy(() => import("@/components/sections/projects"));
const Contact = lazy(() => import("@/components/sections/contact"));

const SectionFallback = () => <div style={{ minHeight: "50vh" }} />;

const IndexPage: React.FC<PageProps> = () => {
    // Check sessionStorage - show loader only on first visit in this session
    const hasLoadedBefore = typeof window !== "undefined" && sessionStorage.getItem("portfolioLoaded") === "true";
    const [loading, setLoading] = useState(!hasLoadedBefore);

    // Stable callback reference - won't trigger SplashLoader re-runs
    const handleLoaderComplete = useCallback(() => {
        setLoading(false);
        if (typeof window !== "undefined") {
            sessionStorage.setItem("portfolioLoaded", "true");
        }
    }, []);

    useEffect(() => {
        if (hasLoadedBefore) return;

        const timer = setTimeout(() => {
            handleLoaderComplete();
        }, 4000); // Slightly longer than animation duration (2.5s + 0.6s fade + buffer)

        return () => clearTimeout(timer);
    }, [hasLoadedBefore, handleLoaderComplete]);

    if (loading) return <Loader onAnimationComplete={handleLoaderComplete} />;

    return (
        <Layout>
            <Home />
            <Suspense fallback={<SectionFallback />}>
                <SectionWrapper section_id="about" title="About Me">
                    <About />
                </SectionWrapper>

                <SectionWrapper section_id="skills" title="Skills">
                    <Skills />
                </SectionWrapper>

                <SectionWrapper section_id="projects" title="Projects">
                    <ProjectsList />
                </SectionWrapper>

                <SectionWrapper section_id="contact" title="Contact">
                    <Contact />
                </SectionWrapper>
            </Suspense>
        </Layout>

    );
};

export const Head = () => <Seo />;
export default IndexPage;