import React, { useEffect, useRef, useState, useCallback } from "react";
import { gsap } from "gsap";
import { CSSPlugin } from "gsap/CSSPlugin";
import SignatureSVG from "../../../images/AP.svg";

if (typeof window !== "undefined") {
  gsap.registerPlugin(CSSPlugin);
}

type SplashLoaderProps = {
  onAnimationComplete?: () => void;
};

const SplashLoader: React.FC<SplashLoaderProps> = ({ onAnimationComplete }) => {
  const svgWrapperRef = useRef<HTMLDivElement | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const hasRunRef = useRef<boolean>(false);
  const onCompleteRef = useRef(onAnimationComplete);
  const [isMounted, setIsMounted] = useState<boolean>(true);

  // Keep callback ref up to date without triggering effect re-runs
  useEffect(() => {
    onCompleteRef.current = onAnimationComplete;
  }, [onAnimationComplete]);

  useEffect(() => {
    // 🔴 Gatsby SSR fix
    if (typeof window === "undefined") return;

    // Prevent multiple runs - animation should only execute once
    if (hasRunRef.current) return;
    hasRunRef.current = true;

    const wrapper = svgWrapperRef.current;
    const container = containerRef.current;

    if (!wrapper || !container) return;

    // Get SVG element from wrapper
    const svgElement = wrapper.querySelector<SVGSVGElement>("svg");
    if (!svgElement) return;

    // SVG paths
    const paths = svgElement.querySelectorAll<SVGGeometryElement>(
      "path, line, polyline, circle, ellipse"
    );

    if (!paths.length) return;

    paths.forEach((path) => {
      const length = path.getTotalLength?.();
      if (!length || isNaN(length)) return;

      // очистка
      path.removeAttribute("fill");
      path.removeAttribute("stroke");
      path.removeAttribute("stroke-width");
      path.removeAttribute("stroke-dasharray");
      path.removeAttribute("stroke-dashoffset");

      // початковий стан
      gsap.set(path, {
        strokeDasharray: length,
        strokeDashoffset: length,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        fill: "none",
        stroke: "#b8f2e6",
        strokeWidth: 1,
      });
    });

    // groups
    svgElement.querySelectorAll<SVGGElement>("g").forEach((g) => {
      g.removeAttribute("fill");
      g.style.fill = "none";
    });

    // timeline
    const tl = gsap.timeline({
      onComplete: () => {
        gsap.to(container, {
          opacity: 0,
          duration: 0.6,
          ease: "power2.inOut",
          onComplete: () => {
            setIsMounted(false);
            onCompleteRef.current?.();
          },
        });
      },
    });

    tl.to(paths, {
      strokeDashoffset: 0,
      duration: 2.5,
      ease: "power2.inOut",
      stagger: {
        each: 0.15,
        ease: "power1.inOut",
      },
    })
      .to(
        paths,
        {
          filter: "drop-shadow(0 0 8px rgba(184, 242, 230, 0.6))",
          duration: 0.4,
          ease: "power2.out",
        },
        "-=0.5"
      )
      .to({}, { duration: 0.8 });

    return () => {
      tl.kill();
    };
  }, []); // Empty dependency array - run once only

  if (!isMounted) return null;

  return (
    <div
      ref={containerRef}
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        width: "100%",
        height: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        backgroundColor: "#1c1c1c",
        zIndex: 100000,
        opacity: 1,
      }}
    >
      {/* background glow */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: "400px",
          height: "400px",
          background:
            "radial-gradient(circle, rgba(184, 242, 230, 0.1) 0%, transparent 70%)",
          animation: "pulse 3s ease-in-out infinite",
          pointerEvents: "none",
        }}
      />

      <div
        ref={svgWrapperRef}
        style={{
          width: "320px",
          height: "auto",
          position: "relative",
          zIndex: 1,
        }}
      >
        <div className="splash-loader-svg">
          <SignatureSVG />
        </div>
      </div>

      <style>{`
        @keyframes pulse {
          0%, 100% {
            opacity: 0.3;
            transform: translate(-50%, -50%) scale(1);
          }
          50% {
            opacity: 0.5;
            transform: translate(-50%, -50%) scale(1.1);
          }
        }
        .splash-loader-svg svg {
          width: 100%;
          height: auto;
          stroke: #b8f2e6;
          fill: none;
          stroke-width: 1;
        }
        .splash-loader-svg svg path,
        .splash-loader-svg svg line,
        .splash-loader-svg svg polyline,
        .splash-loader-svg svg circle,
        .splash-loader-svg svg ellipse {
          fill: none;
          stroke: #b8f2e6;
          stroke-width: 1;
        }
      `}</style>
    </div>
  );
};

export default SplashLoader;